package factories

import (
	"context"
	"database/sql"
	"fmt"
	"github.com/go-faker/faker/v4"
	"mortenvistisen/internal/storage"
	"mortenvistisen/models"
	"time"
)

// Factory declarations below are generated by Andurel.

type NewsletterFactory struct {
	models.NewsletterEntity
}

type NewsletterOption func(*NewsletterFactory)

func BuildNewsletter(opts ...NewsletterOption) models.NewsletterEntity {
	f := &NewsletterFactory{
		NewsletterEntity: models.NewsletterEntity{
			Title:           faker.Word(),
			Slug:            sql.NullString{String: faker.Word(), Valid: true},
			MetaTitle:       faker.Word(),
			MetaDescription: faker.Word(),
			IsPublished:     sql.NullBool{Bool: randomBool(), Valid: true},
			ReleasedAt:      sql.NullTime{Time: time.Now(), Valid: true},
			Content:         sql.NullString{String: faker.Word(), Valid: true},
			ImageLink:       sql.NullString{String: faker.Word(), Valid: true},
			MetaImageLink:   sql.NullString{String: faker.Word(), Valid: true},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.NewsletterEntity
}

func CreateNewsletter(ctx context.Context, exec storage.Executor, opts ...NewsletterOption) (models.NewsletterEntity, error) {
	built := BuildNewsletter(opts...)

	entity := models.NewsletterEntity{
		ID:              built.ID,
		CreatedAt:       time.Now(),
		UpdatedAt:       time.Now(),
		Title:           built.Title,
		Slug:            built.Slug,
		MetaTitle:       built.MetaTitle,
		MetaDescription: built.MetaDescription,
		IsPublished:     built.IsPublished,
		ReleasedAt:      built.ReleasedAt,
		Content:         built.Content,
		ImageLink:       built.ImageLink,
		MetaImageLink:   built.MetaImageLink,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.NewsletterEntity{}, err
	}

	return entity, nil
}

func CreateNewsletters(ctx context.Context, exec storage.Executor, count int, opts ...NewsletterOption) ([]models.NewsletterEntity, error) {
	newsletters := make([]models.NewsletterEntity, 0, count)

	for i := 0; i < count; i++ {
		entity, err := CreateNewsletter(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create newsletter %d: %w", i+1, err)
		}
		newsletters = append(newsletters, entity)
	}

	return newsletters, nil
}

func WithNewslettersTitle(value string) NewsletterOption {
	return func(f *NewsletterFactory) {
		f.NewsletterEntity.Title = value
	}
}

